package com.aoo.bcg.wordcard;import java.util.*;/**宜昌花牌：移植 YCHPRoomEnum/YCHPHuUtil 的花精、六套固定组合与动作计分。*/public final class YchpRules{public record Config(int playerCount,int drawRemoval,int charge,boolean selfDrawMandatory,boolean oppositeCannotChi,boolean guChou,boolean scoreFloorZero){public Config{if(playerCount<2||playerCount>4||drawRemoval!=0)throw new IllegalArgumentException("invalid YCHP room");}}private static final List<List<Integer>>SPECIAL=List.of(List.of(21,22,23),List.of(24,11,26),List.of(30,13,31),List.of(17,25,32),List.of(18,19,33),List.of(27,28,29));private YchpRules(){}public static List<Integer>deck(){List<Integer>x=new ArrayList<>(144);for(int suit=1;suit<=3;suit++)for(int r=1;r<=9;r++)for(int c=1;c<=4;c++)x.add((suit*10+r)*100+c);for(int t=41;t<=47;t++)for(int c=1;c<=4;c++)x.add(t*100+c);for(int t=51;t<=58;t++)x.add(t*100+1);return List.copyOf(x);}public static int type(int c){return c/100;}public static boolean flower(int c){return type(c)>50;}public static boolean legalChi(Collection<Integer>h,int e,Set<Integer>passed,boolean noOpp,boolean opp){int t=type(e);if(passed.contains(t)||t>=40)return false;List<Integer>x=h.stream().map(YchpRules::type).toList();return x.contains(t-1)&&x.contains(t+1)||x.contains(t+1)&&x.contains(t+2);}public static boolean canHu(Collection<Integer>cards,int points){List<Integer>t=cards.stream().filter(c->!flower(c)).map(YchpRules::type).toList();return t.size()%3==2&&(points>0||SPECIAL.stream().anyMatch(t::containsAll));}public static Integer colorWin(Collection<Integer>c){return(int)c.stream().filter(YchpRules::flower).count();}public static long winnerScore(int p,Integer flowers,int charge,int wp,int lp){return Math.max(1,p)+flowers+charge+wp+lp;}}
